func (t Event) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "board.created":
		return t.AsBoardCreatedEvent()
	case "board.policy_changed":
		return t.AsBoardPolicyChangedEvent()
	case "joincode.created":
		return t.AsJoinCodeCreatedEvent()
	case "joincode.revoked":
		return t.AsJoinCodeRevokedEvent()
	case "member.joined":
		return t.AsMemberJoinedEvent()
	case "message.posted":
		return t.AsMessagePostedEvent()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

